CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE customers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name varchar(160) NOT NULL, email varchar(255), phone varchar(50), address text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES customers(id) ON DELETE RESTRICT, title varchar(220) NOT NULL, trade varchar(24) NOT NULL CHECK (trade IN ('ELECTRICAL','HVAC','SOLAR','PLUMBING')), status varchar(32) NOT NULL DEFAULT 'INTAKE' CHECK (status IN ('INTAKE','SURVEY','SCHEDULED','IN_PROGRESS','COMPLETED','INVOICED','CANCELLED')), site_address text NOT NULL, description text, scheduled_for timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), version bigint NOT NULL DEFAULT 0);
CREATE INDEX jobs_status_idx ON jobs(status); CREATE INDEX jobs_customer_idx ON jobs(customer_id);
CREATE TABLE surveys (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_id uuid NOT NULL REFERENCES jobs(id) ON DELETE CASCADE, notes text NOT NULL, access_requirements text, estimated_hours numeric(10,2) CHECK (estimated_hours IS NULL OR estimated_hours >= 0), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE installation_reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_id uuid NOT NULL REFERENCES jobs(id) ON DELETE CASCADE, notes text NOT NULL, materials_used text, safety_checked boolean NOT NULL DEFAULT false, customer_accepted boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE completion_documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_id uuid NOT NULL REFERENCES jobs(id) ON DELETE CASCADE, description text NOT NULL, acknowledged_by varchar(160), completed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE invoices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_id uuid NOT NULL UNIQUE REFERENCES jobs(id) ON DELETE RESTRICT, invoice_number varchar(50) NOT NULL UNIQUE, description text NOT NULL, net_amount numeric(13,2) NOT NULL CHECK (net_amount >= 0), tax_rate numeric(5,4) NOT NULL CHECK (tax_rate BETWEEN 0 AND 1), currency char(3) NOT NULL DEFAULT 'EUR', issued_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE job_events (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, job_id uuid NOT NULL REFERENCES jobs(id) ON DELETE CASCADE, event_type varchar(40) NOT NULL, description text, actor varchar(100) NOT NULL, occurred_at timestamptz NOT NULL DEFAULT now());
